import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"查看和上传工程文件","description":"在工程资源页查看、上传和打开文件，复制资源地址，并核对操作结果。","frontmatter":{"title":"查看和上传工程文件","description":"在工程资源页查看、上传和打开文件，复制资源地址，并核对操作结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/project-files.md","filePath":"zh/使用指南/查看和上传工程文件.md"}'),i={name:"zh/guide/project-files.md"};function l(d,t,n,s,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="查看和上传工程文件" tabindex="-1">查看和上传工程文件 <a class="header-anchor" href="#查看和上传工程文件" aria-label="Permalink to &quot;查看和上传工程文件&quot;">​</a></h1><p>需要把图片、资料等文件交给当前工程使用时，可以进入工程的<strong>资源</strong>页。这里的文件存放在工程对象库，与编辑器中的源码文件分开管理。</p><p>开始前，你需要已经能打开一个工程的“应用开发”，并具备相应操作权限。如果工程还不能打开，先请工程管理员准备好工程，再从本页开始。</p><h2 id="_1-打开资源页" tabindex="-1">1. 打开资源页 <a class="header-anchor" href="#_1-打开资源页" aria-label="Permalink to &quot;1. 打开资源页&quot;">​</a></h2><ol><li>从公共入口登录组织，进入“工程管理”。</li><li>找到要操作的工程，打开“应用开发”。</li><li>在工程工作区选择 <strong>“资源”</strong>。</li><li>先核对工程名称，再查看文件列表。</li></ol><p>列表显示名称、类型、大小和更新时间。没有文件时，页面会提示“当前目录还没有对象库文件，请点击‘上传文件’开始。”。</p><p>文件多时，可在列表底部翻页或调整每页条数。需要重新核对内容时，点击“刷新”。不要因为只看到当前页，就认为整个工程只有这些文件。</p><h2 id="_2-上传一个文件" tabindex="-1">2. 上传一个文件 <a class="header-anchor" href="#_2-上传一个文件" aria-label="Permalink to &quot;2. 上传一个文件&quot;">​</a></h2><ol><li>点击 <strong>“上传文件”</strong>，从电脑选择准备好的文件，一次选择一个。</li><li>留意“正在上传”的进度，等待操作结束。</li><li>确认列表出现该文件，核对名称、大小和更新时间。</li><li>点击“刷新”，再次确认文件仍在。</li></ol><p>传输显示 100% 后，还要等待操作结束并确认列表结果。操作未结束时，不要连续点击上传。</p><p>需要中止时，在进度区域点击 <strong>“取消上传”</strong>。等当前操作结束，再刷新列表核对结果；需要继续时，重新选择文件上传。</p><p>第一次练习可用一份不含敏感信息的小文件。较大文件的限制请先与工程管理员确认，以当前页面和交付说明为准。</p><h2 id="_3-打开文件或复制地址" tabindex="-1">3. 打开文件或复制地址 <a class="header-anchor" href="#_3-打开文件或复制地址" aria-label="Permalink to &quot;3. 打开文件或复制地址&quot;">​</a></h2><p>点击文件名或该行的 <strong>“打开”</strong>，可查看对应文件。浏览器怎样显示取决于文件类型，不是所有文件都会像图片一样直接预览。</p><p>取得地址时：</p><ol><li>点击该行的 <strong>“复制资源地址”</strong>。</li><li>看到复制成功提示后，将地址粘贴到需要的位置。</li><li>如果出现复制失败对话框，可选中其中的完整地址手动复制，或点击“再次复制”。</li></ol><p><strong>资源地址仍需要登录和相应工程权限，不是公开分享链接。</strong> 不要通过发送地址来代替为对方分配访问权限。</p><h2 id="_4-不再需要文件时移除" tabindex="-1">4. 不再需要文件时移除 <a class="header-anchor" href="#_4-不再需要文件时移除" aria-label="Permalink to &quot;4. 不再需要文件时移除&quot;">​</a></h2><p>先确认工程、文件名和用途，避免影响仍在使用它的页面。需要保留的文件，应先保存好副本。</p><ol><li>点击该行的 <strong>“移除”</strong>。</li><li>在“移除文件”对话框核对文件名。</li><li>不确定时点击“取消”；确认不再需要时才点击 <strong>“确认移除”</strong>。</li><li>等操作结束，刷新列表，确认文件不再显示。</li></ol><p>移除某页最后一个文件后，列表可能返回前面的页，请先检查页码，不要误以为其他文件也被删除。不要假定移除后一定能从回收站找回。</p><h2 id="操作没成功时怎么办" tabindex="-1">操作没成功时怎么办 <a class="header-anchor" href="#操作没成功时怎么办" aria-label="Permalink to &quot;操作没成功时怎么办&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到的情况</th><th>先做什么</th></tr></thead><tbody><tr><td>不能打开工程或资源页</td><td>核对组织和工程，联系工程管理员确认权限与开发环境状态</td></tr><tr><td>上传中断或失败</td><td>等当前操作结束，刷新列表核对文件是否已出现，再决定是否重试</td></tr><tr><td>打开地址时要求登录</td><td>使用有该工程权限的账号登录，不把地址当成免登录链接</td></tr><tr><td>复制失败</td><td>从对话框手动复制完整地址，或点击“再次复制”</td></tr><tr><td>移除失败或结果不明确</td><td>保留提示，刷新列表确认实际状态，不连续重复确认</td></tr></tbody></table><p>仍有问题时，记录工程名称、操作、发生时间和页面提示，交给维护人员。不要提供密码、登录 Cookie 或含敏感信息的文件。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>确认文件操作结果后，再按工程用途使用这些资料。上传或移除开发资料不会替你完成工程发布；需要更新正在使用的工程时，请按交付安排进行发布与核对。</p>',26)])])}const g=a(i,[["render",l]]);export{c as __pageData,g as default};
